        { id: "l4k6", type: "count", front: "أنواع النظام مرتبة حسب أولويتها", n: 3, lead: "أنواعه الثلاثة بالترتيب:", items: ["الأنظمة الأساسية ذات الصبغة الدستورية", "الأنظمة (القوانين) العادية", "اللوائح والقرارات الإدارية ذات الصفة التنظيمية التشريعية"], pg: "37" },
        { id: "l4k7", type: "count", front: "طريقتا إصدار الأنظمة الأساسية ومثالاهما", n: 2, lead: "تصدرها السلطة التشريعية:", items: ["بمبادرة منها: القانون رقم (81) لإنشاء المحكمة العليا للفصل في دستورية القوانين في مصر", "بناءً على نص دستوري: المادة (25) من الدستور الفرنسي"], pg: "37–38" },
        { id: "l4k8", type: "rule", front: "هل الأنظمة الأساسية مصدر للقانون الدستوري؟", rule: "استقر الرأي على أنها مصدر، لأنها تتناول مواضيع دستورية من الناحية الموضوعية.", exc: "لكن مخالفتها لا تقود إلى الدفع بعدم دستورية القانون المخالف لها، كما هو حال النصوص الدستورية.", pg: "38" },
        { id: "l4k9", type: "count", front: "سببا لجوء المشرع الدستوري إلى الأنظمة الأساسية", n: 2, lead: "أمران:", items: ["الحد من زيادة عدد النصوص الدستورية", "سهولة إجراء التعديلات عليها حذفاً أو إضافة لأنها خارج إطار الدستور"], pg: "38" },
        { id: "l4k10", type: "count", front: "أدوار العرف الدستوري في الأنظمة المعاصرة", n: 3, lead: "أدواره الثلاثة بحسب الحاجة أو الضرورة:", items: ["المفسر", "المكمل", "المعدل"], pg: "39" }
