      objective: [
        { id: "l4o1", k: "tf", q: "تتولى إعداد الوثيقة الدستورية الهيئة نفسها المكلفة بصياغة القوانين العادية.", a: false, why: "تتولى إعدادها هيئة خاصة غير الهيئة المكلفة بصياغة القوانين العادية: السلطة التأسيسية الأصلية أو المنشأة.", pg: "36" },
        { id: "l4o2", k: "tf", q: "استقر رأي غالبية الفقهاء على أن مقدمة الدستور (الديباجة) أدنى قيمة قانونية من نصوصه.", a: false, why: "استقر رأي غالبيتهم على تمتعها بنفس القيمة القانونية لنصوص الدستور، لأنها جزء لا يتجزأ منه مرّ بنفس مراحل النقاش والصياغة والإقرار.", pg: "36–37" },
        { id: "l4o3", k: "tf", q: "الأنظمة الأساسية مصدر للقانون الدستوري، ومع ذلك لا تقود مخالفتها إلى الدفع بعدم دستورية القانون المخالف لها.", a: true, why: "استقر الرأي على أنها مصدر لتناولها مواضيع دستورية من الناحية الموضوعية، لكن مخالفتها لا تقود إلى الدفع بعدم الدستورية كما هو حال النصوص الدستورية.", pg: "38" },
        { id: "l4o4", k: "tf", q: "نظام الجنسية من الأنظمة الأساسية ذات الصبغة الدستورية في كل الدول.", a: false, why: "دستورية الأنظمة الأساسية تختلف من دولة لأخرى، فنظام الجنسية قد يكون دستورياً في دولة وعادياً في أخرى.", pg: "37" },
        { id: "l4o5", k: "tf", q: "يمارس الرئيس الفرنسي دوراً كبيراً في الشؤون الخارجية دون مرجعية في الدستور، بل اقتضاه العرف.", a: true, why: "هذا أحد أمثلة الكتاب على دور العرف الدستوري في البلاد ذات الدساتير المكتوبة.", pg: "38–39" },
        { id: "l4o6", k: "mcq", q: "أي الآتي ليس من طرق وضع الدستور التي حصرتها الأدبيات؟", opts: ["المنحة", "الجمعية التأسيسية", "العقد", "إعلان الحقوق"], a: 3, why: "طرق وضع الدستور أربع: المنحة، والعقد، والجمعية التأسيسية، والاستفتاء الشعبي (الدستوري)؛ أما إعلانات الحقوق فإحدى الوثائق الدستورية لا طريقة لوضع الدستور.", pg: "35–37" },
        { id: "l4o7", k: "mcq", q: "إلى أي أنواع النظام ينتمي نظام خدمة الضباط؟", opts: ["الأنظمة الأساسية ذات الصبغة الدستورية", "الأنظمة العادية", "اللوائح التنفيذية", "لوائح الضبط الإداري"], a: 1, why: "الأنظمة العادية تنظم شؤون الحياة والمهن، كنظام خدمة الضباط والصيادلة والتعليم؛ أما اللوائح التنفيذية ولوائح الضبط الإداري فمن النوع الثالث.", pg: "37" },
        { id: "l4o8", k: "mcq", q: "ما المثال الذي ساقه الكتاب للأنظمة الأساسية الصادرة بناءً على نص دستوري؟", opts: ["القانون رقم (81) الخاص بالمحكمة العليا في مصر", "النظام الأساسي للحكم السعودي", "المادة (25) من الدستور الفرنسي", "إعلان الحقوق الفرنسي"], a: 2, why: "مثال الصادرة بناءً على نص دستوري المادة (25) من الدستور الفرنسي؛ أما القانون رقم (81) في مصر فمثال الصادرة بمبادرة من السلطة التشريعية.", pg: "38" },
        { id: "l4o9", k: "mcq", q: "لماذا صار النظام الأمريكي قريب الشبه من النظام البرلماني مع أنه رئاسي طبقاً للنصوص؟", opts: ["لأن الواقع أقامه على التعاون بين السلطات لا الفصل التام", "لأن الرئيس يمارس دوراً كبيراً في الشؤون الخارجية دون مرجعية دستورية", "لأن القضاء يراقب دستورية التشريعات بنص دستوري صريح", "لأن مؤسسيه الأوائل أرادوه قائماً على التعاون بين السلطات"], a: 0, why: "الواقع جعله قائماً على التعاون بين السلطات، لا الفصل التام الذي أراده المؤسسون الأوائل، والقضائية فيه تراقب دستورية التشريعات دون نص صريح؛ أما دور الرئيس في الشؤون الخارجية دون مرجعية دستورية فمثال فرنسي.", pg: "38–39" },
        { id: "l4o10", k: "fill", q: "الهيئة التي تتولى إعداد الوثيقة الدستورية عند وجود دستور قائم يحدد صلاحياتها تسمى السلطة ____.", a: "التأسيسية المنشأة", opts: ["التأسيسية الأصلية", "التشريعية", "التأسيسية المنشأة", "التنفيذية"], why: "تسمى السلطة التأسيسية المنشأة عند وجود دستور قائم يحدد صلاحياتها، والأصلية عند صياغة دستور جديد لأول مرة؛ وهي هيئة خاصة غير الهيئة المكلفة بصياغة القوانين العادية.", pg: "36" },
        { id: "l4o11", k: "fill", q: "أهم مصدر للقاعدة الدستورية في البلاد ذات الدساتير المكتوبة هو ____.", a: "الوثيقة الدستورية", opts: ["القوانين الأساسية", "العرف الدستوري", "إعلانات الحقوق", "الوثيقة الدستورية"], why: "الوثيقة الدستورية أهم مصدر في البلاد ذات الدساتير المكتوبة، وقد تكون واحدة أو متعددة تشمل إعلانات الحقوق.", pg: "35–36" },
        { id: "l4o12", k: "fill", q: "أدوار العرف الدستوري في الأنظمة المعاصرة: المفسر، أو المكمل، أو ____، حسب الحاجة أو الضرورة.", a: "المعدل", opts: ["المنشئ", "الملغي", "المعدل", "المقنن"], why: "أدواره ثلاثة: المفسر، والمكمل، والمعدل، حسب الحاجة أو الضرورة.", pg: "39" }
      ],
