        { id: "l4e2", q: "تكلّم عن الأنظمة الأساسية مصدراً للقاعدة الدستورية: تعريف النظام وأنواعه، وطريقتا إصدارها، ومدى اعتبارها مصدراً، وسبب لجوء المشرع الدستوري إليها.", pg: "37–38", points: [
          { x: "النظام (التشريع أو القانون): مجموعة القواعد القانونية (النظامية) التي تصدرها السلطة التشريعية (التنظيمية) وفق إجراءات منصوص عليها، وهو المصدر الرسمي المرجوع إليه.", pg: "37" },
          { x: "أنواعه ثلاثة مرتبة حسب أولويتها: الأنظمة الأساسية ذات الصبغة الدستورية، ثم الأنظمة العادية، ثم اللوائح والقرارات الإدارية ذات الصفة التنظيمية التشريعية.", pg: "37" },
          { x: "الأنظمة الأساسية تتناول مواضيع ذات صبغة دستورية، وسميت أساسية لأهميتها ودورها في معالجتها، وتختلف دستوريتها من دولة لأخرى كنظام الجنسية.", pg: "37–38" },
          { x: "تصدرها السلطة التشريعية بمبادرة منها، كالقانون رقم (81) الخاص بإنشاء المحكمة العليا للفصل في دستورية القوانين في مصر، أو بناءً على نص دستوري كالمادة (25) من الدستور الفرنسي.", pg: "38" },
          { x: "استقر الرأي على أنها مصدر لتناولها مواضيع دستورية من الناحية الموضوعية، لكن مخالفتها لا تقود إلى الدفع بعدم دستورية القانون المخالف لها كما هو حال النصوص الدستورية.", pg: "38" },
          { x: "يلجأ إليها المشرع الدستوري لأمرين: الحد من زيادة عدد النصوص الدستورية، وسهولة تعديلها حذفاً أو إضافة لأنها خارج إطار الدستور؛ ولذا تُنظَّم الانتخابات والدوائر الانتخابية والسلطات العامة غالباً بقوانين أساسية أو عادية.", pg: "38" },
          { x: "وقد لجأ النظام الأساسي للحكم إلى هذا الأسلوب حين أحال تنظيم السلطات العامة إلى أنظمة خارجه مكتفياً بالإشارة إليها بإيجاز في مواد قليلة.", pg: "38" }
        ] },
        { id: "l4e3", q: "بيّن دور العرف الدستوري في البلاد ذات الدساتير المكتوبة، ومثّل له من الكتاب.", pg: "38–39", points: [
          { x: "يبين العرف الدستوري مضامين النصوص ويوضحها في الدساتير المقتضبة، أو التي مر عليها زمن طويل فتجاوزها الواقع.", pg: "38" },
          { x: "الرئيس الفرنسي يمارس دوراً كبيراً في الشؤون الخارجية دون مرجعية في الدستور، بل اقتضاه العرف.", pg: "38–39" },
          { x: "النظام الأمريكي رئاسي طبقاً للنصوص، لكن الواقع جعله قريب الشبه من البرلماني لقيامه على التعاون بين السلطات لا الفصل التام: فالتنفيذية تشترك في التشريع، والكونجرس يتدخل في اختصاصات التنفيذية، والقضائية تراقب دستورية التشريعات دون نص صريح.", pg: "39" },
          { x: "في الحالة السعودية شكّل العرف الدستوري مصدراً هاماً، ومن نماذج أهميته توارث الحكم وحصره في الأسرة الحاكمة السعودية، والمجالس المفتوحة.", pg: "39" },
          { x: "وأدواره في الأنظمة المعاصرة ثلاثة: المفسر، أو المكمل، أو المعدل، حسب الحاجة أو الضرورة.", pg: "39" }
        ] }
